INSERT INTO feature VALUES('deployment-offers','runtime','A deployment''s offers: each world''s requirement row answered by its site''s offer','deployment-file','partial','notable',NULL,'`world w requires [ … ] ;` states as a row what a role placed at `w` needs: a host interface by its name, and an effect theory at fixed sorts under a label, each entry refused as a row refuses it and a theory under no label refused `UnlabelledRequirement`. A site''s file answers with one `offers [ … ] ;`, granting host interfaces by name and binding each label to a model module it declares, an interface no host declares, a module it does not declare, an entry written twice and a second offer each refused. `gandr check` of a manifold reads the program it deploys before any process starts: a placement of a world the program does not declare is refused by the world''s name, and a world written with a requirement finds its site''s file among those the manifold imports by the site''s key and has its row judged entry by entry, each entry unanswered refused by its name. A label is answered by its module taken as a functor''s argument at `Model(T)` and the row''s sorts, refused naming both types at other sorts; a host interface by the site''s `Authority` attenuated to its operations, refused naming both capabilities where it holds fewer. An offer reads its module through a translation, `store = M via f` or `store = M renaming { a as b }`, and the manifold''s `pub def translation : Translation` admits it by its policy before the module is judged: `Exact`, the default, admits none and refuses the label by name, `Path` admits a renaming and a flow whose every member renames one member and refuses the member that computes, and `Flow` admits any flow. An admitted translation is applied to the module in the text the check judges. Code at a world is typed against its row: a migration''s body checks under the interfaces its world''s requirement names whole, as a function''s body checks under its declared row, and a perform outside them is refused `TypeMismatch` as in a function (#3545). The host that serves a world answers a migration''s body from its own authority, attenuated to the host interfaces of the world''s row: a print at `far` prints at the far host, and an interface outside the row reaches no handler (#3546). The instance a labelled entry binds at that body, with its handler from the offer''s model (#6546), and the endpoint a translation hosts (#6271), are owed.','surface-grammar surface-lowering core-checker surface-diagnostics surface-dispatcher surface-evaluate surface-driver runtime-emitter runtime-net','corpus/ledger/features/deployment-offers.gandr corpus/model/deployments/offers.gandr corpus/model/deployments/offers.site.gandr corpus/model/deployments/offers.manifold.gandr corpus/model/translations/translated.gandr corpus/model/translations/translated.versions.gandr corpus/model/translations/translated.site.gandr corpus/model/translations/translated.manifold.gandr corpus/pathological/worlds/offers.gandr corpus/pathological/worlds/offered.gandr corpus/pathological/worlds/requires.gandr corpus/pathological/worlds/rows.gandr corpus/pathological/worlds/translated.gandr corpus/pathological/worlds/rewritten.gandr crates/surface-lowering/src/lower/world/tests.rs crates/core-checker-base/src/worlds/tests.rs crates/core-checker-base/tests/worlds.rs crates/surface-dispatcher/tests/manifold.rs crates/surface-driver/tests/cli.rs crates/surface-driver/tests/net.rs crates/runtime-emitter/tests/world.rs','corpus/ledger/features/deployment-offers.gandr','#6546 #6271');
